"""Provider execution for one fully assembled semantic request."""

from __future__ import annotations

import json
from dataclasses import replace
from typing import Any

from anaxigraph.architecture_charter_contract import compact_architecture_charter
from anaxigraph.config import SemanticConfig
from anaxigraph.semantic import SEMANTIC_SCHEMA_VERSION, SemanticAnalysisError, SemanticResult
from anaxigraph.semantic_graph import _source_chunks
from anaxigraph.semantic_parallel import parallel_map
from anaxigraph.semantic_request_support import compact_dossier
from anaxigraph.semantic_taxonomy_runner import (
    analyze_taxonomy_proposal,
    analyze_taxonomy_review,
)


def analyze_semantic_request(
    provider: Any,
    request: dict[str, Any],
    semantic: SemanticConfig,
) -> SemanticResult:
    """Execute a request with bounded chunking independent of index location."""

    provider = _OutputRecovery(provider, semantic)
    if request["analysis_kind"] == "taxonomy_proposal":
        return analyze_taxonomy_proposal(provider, request, semantic)
    if request["analysis_kind"] == "taxonomy_review":
        return analyze_taxonomy_review(provider, request, semantic)
    if request["analysis_kind"] == "synthesis":
        return _analyze_synthesis(provider, request, semantic)
    source = str(request.get("source") or "")
    if request["analysis_kind"] != "intrinsic" or len(source) <= semantic.max_source_chars:
        return provider.analyze(request)
    return _analyze_intrinsic_chunks(provider, request, semantic, source)


class _OutputRecovery:
    """Retry confirmed output truncation once, preserving the schema and all reported usage."""

    def __init__(self, provider: Any, semantic: SemanticConfig) -> None:
        self.provider, self.semantic = provider, semantic

    def analyze(self, request: dict[str, Any]) -> SemanticResult:
        try:
            return self.provider.analyze(request)
        except SemanticAnalysisError as exc:
            limit = int(request.get("max_output_tokens") or self.semantic.max_output_tokens)
            ceiling = self.semantic.max_output_tokens_on_retry
            if not exc.output_truncated or ceiling <= limit:
                raise
            previous = exc
        retry = {
            **request,
            "max_output_tokens": min(limit * 2, ceiling),
            "output_recovery": "The previous response hit its output limit. Return complete JSON; keep each statement concise.",
        }
        try:
            result = self.provider.analyze(retry)
        except SemanticAnalysisError as exc:
            for key, value in _combined_usage(exc, previous).items():
                setattr(exc, key, value)
            raise
        return replace(result, **_combined_usage(result, previous))


def _combined_usage(result: Any, previous: SemanticAnalysisError) -> dict[str, Any]:
    return {
        **{
            key: getattr(result, key) + getattr(previous, key)
            for key in (
                "input_tokens",
                "output_tokens",
                "cache_read_input_tokens",
                "cache_creation_input_tokens",
            )
        },
        "usage_reported": result.usage_reported and previous.usage_reported,
    }


def _analyze_intrinsic_chunks(
    provider: Any,
    request: dict[str, Any],
    semantic: SemanticConfig,
    source: str,
) -> SemanticResult:
    symbols = request.get("deterministic_facts", {}).get("symbols") or []
    chunks = _source_chunks(source, symbols, semantic.max_source_chars)
    requests = []
    for index, (start, end, content) in enumerate(chunks, start=1):
        partial = dict(request)
        partial["analysis_kind"] = "intrinsic_chunk"
        partial["chunk"] = {
            "index": index,
            "total": len(chunks),
            "start_line": start,
            "end_line": end,
        }
        partial["source"] = content
        requests.append(partial)
    results = parallel_map(provider.analyze, requests, semantic.max_parallel_jobs)
    partials = [result.value for result in results]
    input_tokens = sum(result.input_tokens for result in results)
    output_tokens = sum(result.output_tokens for result in results)
    synthesis = {
        **{key: value for key, value in request.items() if key != "source"},
        "schema_version": SEMANTIC_SCHEMA_VERSION,
        "analysis_kind": "intrinsic_synthesis",
        "chunk_dossiers": partials,
    }
    result = provider.analyze(synthesis)
    return SemanticResult(
        value=result.value,
        confidence=result.confidence,
        evidence=result.evidence,
        input_tokens=input_tokens + result.input_tokens,
        output_tokens=output_tokens + result.output_tokens,
    )


def _analyze_synthesis(
    provider: Any,
    request: dict[str, Any],
    semantic: SemanticConfig,
) -> SemanticResult:
    children = list(request.get("child_dossiers") or [])
    if len(json.dumps(request, default=str)) <= semantic.max_source_chars or len(children) < 2:
        return provider.analyze(request)

    base = {key: value for key, value in request.items() if key != "child_dossiers"}
    batches = _payload_batches(children, semantic.max_source_chars, base)
    partials, input_tokens, output_tokens = _run_synthesis_chunks(
        provider, base, batches, semantic.max_parallel_jobs
    )
    reduction_width = max(2, min(20, semantic.max_context_modules))
    partials, reduction_input, reduction_output = _reduce_synthesis_partials(
        provider, base, partials, reduction_width, semantic.max_parallel_jobs
    )

    final_request = {**base, "analysis_kind": "synthesis", "child_dossiers": partials}
    result = provider.analyze(final_request)
    return SemanticResult(
        value=result.value,
        confidence=result.confidence,
        evidence=result.evidence,
        input_tokens=input_tokens + reduction_input + result.input_tokens,
        output_tokens=output_tokens + reduction_output + result.output_tokens,
    )


def _payload_batches(
    children: list[dict[str, Any]], max_chars: int, base: dict[str, Any]
) -> list[list[dict[str, Any]]]:
    overhead = len(json.dumps(base, default=str)) + 500
    budget = max(1_000, max_chars - overhead)
    batches: list[list[dict[str, Any]]] = []
    current: list[dict[str, Any]] = []
    size = 0
    for child in children:
        child_size = len(json.dumps(child, default=str)) + 1
        if current and size + child_size > budget:
            batches.append(current)
            current = []
            size = 0
        current.append(child)
        size += child_size
    if current:
        batches.append(current)
    return batches


def _run_synthesis_chunks(
    provider: Any,
    base: dict[str, Any],
    batches: list[list[dict[str, Any]]],
    parallel_jobs: int,
) -> tuple[list[dict[str, Any]], int, int]:
    requests = []
    for index, batch in enumerate(batches, start=1):
        requests.append(
            {
                **base,
                "analysis_kind": "synthesis_chunk",
                "chunk": {"index": index, "total": len(batches)},
                "child_dossiers": batch,
            }
        )
    results = parallel_map(provider.analyze, requests, parallel_jobs)
    partials = [_partial_dossier(index, result) for index, result in enumerate(results, start=1)]
    input_tokens = sum(result.input_tokens for result in results)
    output_tokens = sum(result.output_tokens for result in results)
    return partials, input_tokens, output_tokens


def _reduce_synthesis_partials(
    provider: Any,
    base: dict[str, Any],
    partials: list[dict[str, Any]],
    width: int,
    parallel_jobs: int,
) -> tuple[list[dict[str, Any]], int, int]:
    input_tokens = output_tokens = 0
    level = 1
    while len(partials) > width:
        groups = [partials[index : index + width] for index in range(0, len(partials), width)]
        requests = []
        for index, batch in enumerate(groups, start=1):
            requests.append(
                {
                    **base,
                    "analysis_kind": "synthesis_reduction",
                    "reduction": {"level": level, "index": index, "total": len(groups)},
                    "child_dossiers": batch,
                }
            )
        results = parallel_map(provider.analyze, requests, parallel_jobs)
        reduced = [_partial_dossier(index, result) for index, result in enumerate(results, start=1)]
        input_tokens += sum(result.input_tokens for result in results)
        output_tokens += sum(result.output_tokens for result in results)
        partials = reduced
        level += 1
    return partials, input_tokens, output_tokens


def _partial_dossier(index: int, result: SemanticResult) -> dict[str, Any]:
    value = (
        compact_architecture_charter(result.value)
        if result.value.get("contract_version") == "architecture-charter-v1"
        else compact_dossier(result.value, detailed="detailed_summary" in result.value)
    )
    return {
        "scope": f"semantic-chunk-{index}",
        "kind": "synthesis",
        "confidence": result.confidence,
        "value": value,
    }

"""Per-run semantic executor selection for agent-funded understanding."""

from __future__ import annotations

import os
import shutil
from dataclasses import replace
from typing import Any

from anaxigraph.semantic_stage_model import (
    STAGE_PROVIDERS,
    STAGE_TIERS,
    SemanticStageModel,
)


def add_semantic_execution_arguments(parser: Any) -> None:
    parser.add_argument(
        "--executor",
        choices=("auto", "mcp", "codex", "claude"),
        default="auto",
        help=(
            "Who processes AI tasks: auto finds the current coding agent; mcp leaves one task "
            "at a time for the connected agent; codex or claude starts that local command-line tool"
        ),
    )
    parser.add_argument(
        "--model",
        help="Worker model; choose explicitly for unattended mapping to avoid an expensive CLI default",
    )
    parser.add_argument(
        "--reasoning-effort",
        help=(
            "Optional reasoning effort for this run's local codex or claude executor; the value "
            "is passed through unvalidated so new effort levels do not require an AnaxiGraph "
            "release"
        ),
    )
    parser.add_argument(
        "--stage-model",
        action="append",
        metavar="TIER=[EXECUTOR:]MODEL[:EFFORT]",
        help=(
            "Override the model for one kind of work this run, repeatable. TIER is module, "
            "group, repository, or taxonomy. Examples: repository=gpt-6-astra:high, "
            "group=claude:claude-sonnet-5:medium. Overrides the repository's stage_models"
        ),
    )
    _add_runtime_limit_arguments(parser)


def _add_runtime_limit_arguments(parser: Any) -> None:
    """How hard to push this run, as opposed to what runs it."""

    parser.add_argument(
        "--parallel-jobs",
        type=int,
        help="Most model calls to run at once, up to the maximum in repository settings",
    )
    parser.add_argument(
        "--timeout-seconds",
        type=int,
        help=(
            "Seconds allowed for each model call; this runtime choice does not make saved AI "
            "descriptions stale"
        ),
    )
    parser.add_argument(
        "--background",
        "--detach",
        action="store_true",
        help=(
            "Start or reuse a durable runner for parallel tasks. It owns retries and progress "
            "after this shell exits; no supervisor script or LLM polling loop is needed"
        ),
    )


def stage_model_overrides(values: list[str] | None) -> dict[str, SemanticStageModel]:
    """Read tiers given on the command line, in the same shape the policy file uses.

    A run is where the cost is felt, so the choice has to be available there and not only in
    a committed file. The parsed result replaces a tier outright rather than merging into it,
    so what a flag says is what runs.
    """

    tiers: dict[str, SemanticStageModel] = {}
    for raw in values or []:
        tier, _, spec = str(raw).partition("=")
        name = tier.strip().lower()
        if name not in STAGE_TIERS or not spec.strip():
            raise ValueError(
                f"--stage-model expects TIER=[EXECUTOR:]MODEL[:EFFORT] where TIER is one of "
                f"{', '.join(STAGE_TIERS)}; received {raw!r}"
            )
        parts = [item.strip() for item in spec.split(":")]
        provider = parts.pop(0).lower() if parts[0].lower() in STAGE_PROVIDERS else ""
        if not parts or not parts[0]:
            raise ValueError(f"--stage-model {name} names an executor but no model")
        tiers[name] = SemanticStageModel(
            provider=provider,
            model=parts[0],
            reasoning_effort=parts[1] if len(parts) > 1 else "",
        )
    return tiers


def understand_execution(args: Any, semantic: Any) -> tuple[Any | None, str]:
    reasoning_effort = getattr(args, "reasoning_effort", None)
    parallel_jobs = getattr(args, "parallel_jobs", None)
    timeout_seconds = getattr(args, "timeout_seconds", None)
    _validate_runtime_limits(parallel_jobs, timeout_seconds)
    if semantic.provider != "agent":
        return _configured_provider_execution(
            args, semantic, reasoning_effort, parallel_jobs, timeout_seconds
        )
    if args.plan_only:
        if (
            args.executor not in {"auto", "mcp"}
            or args.model
            or reasoning_effort
            or parallel_jobs
            or timeout_seconds
        ):
            raise ValueError("--plan-only cannot be combined with a local agent executor or model")
        return None, "plan_only"
    executor = detected_agent_executor() if args.executor == "auto" else args.executor
    return _local_agent_execution(
        args,
        semantic,
        executor,
        reasoning_effort,
        parallel_jobs,
        timeout_seconds,
    )


def _configured_provider_execution(
    args: Any,
    semantic: Any,
    reasoning_effort: str | None,
    parallel_jobs: int | None,
    timeout_seconds: int | None,
) -> tuple[None, str]:
    if args.executor not in {"auto", "mcp"}:
        raise ValueError("--executor is only valid when semantic.provider is agent")
    if args.model:
        raise ValueError("Set semantic.model in policy for a configured model provider")
    if reasoning_effort:
        raise ValueError(
            "--reasoning-effort is only valid for an agent-funded local Codex or Claude executor"
        )
    if parallel_jobs or timeout_seconds:
        raise ValueError(
            "--parallel-jobs and --timeout-seconds are only valid for an agent-funded local "
            "executor"
        )
    return None, semantic.provider


def _local_agent_execution(
    args: Any,
    semantic: Any,
    executor: str,
    reasoning_effort: str | None,
    parallel_jobs: int | None,
    timeout_seconds: int | None,
) -> tuple[Any | None, str]:
    if executor == "mcp":
        if args.model or reasoning_effort or parallel_jobs or timeout_seconds:
            raise ValueError("--model and --reasoning-effort require a local agent executor")
        return None, "mcp"
    if shutil.which(executor) is None:
        raise ValueError(f"The {executor} CLI is not installed or not available on PATH")
    return replace(
        semantic,
        provider=executor,
        model=args.model or "",
        reasoning_effort=reasoning_effort or "",
        stage_models={
            **(semantic.stage_models or {}),
            **stage_model_overrides(getattr(args, "stage_model", None)),
        },
        max_parallel_jobs=min(
            parallel_jobs or semantic.max_parallel_jobs, semantic.max_parallel_jobs
        ),
        timeout_seconds=timeout_seconds or semantic.timeout_seconds,
    ), executor


def _validate_runtime_limits(
    parallel_jobs: int | None,
    timeout_seconds: int | None,
) -> None:
    if parallel_jobs is not None and parallel_jobs < 1:
        raise ValueError("--parallel-jobs must be at least one")
    if timeout_seconds is not None and timeout_seconds < 1:
        raise ValueError("--timeout-seconds must be at least one")


def detected_agent_executor() -> str:
    if os.environ.get("CODEX_THREAD_ID") and shutil.which("codex"):
        return "codex"
    claude_environment = any(
        os.environ.get(name)
        for name in ("CLAUDECODE", "CLAUDE_CODE_ENTRYPOINT", "CLAUDE_SESSION_ID")
    )
    if claude_environment and shutil.which("claude"):
        return "claude"
    return "mcp"

"""Which model does which kind of work.

Most of a mapping run is one description per file. Those do not need the model that writes
the repository Charter, and paying for it there is the largest avoidable cost in a refresh.
The tier a request belongs to is already implied by what the request asks for, so naming a
model per tier needs no new plumbing through the planner or the worker protocol.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

STAGE_TIERS = ("module", "group", "repository", "taxonomy")
STAGE_PROVIDERS = ("codex", "claude", "command")


@dataclass(frozen=True, slots=True)
class SemanticStageModel:
    """A model chosen for one kind of work rather than for the whole run.

    The executor belongs here too. Which command-line tool runs is part of naming a model:
    a tier cannot ask for a Claude model while the run is launched against Codex unless it
    can say so. An empty field keeps whatever the run was launched with.
    """

    provider: str = ""
    model: str = ""
    reasoning_effort: str = ""


def parse_stage_models(value: Any) -> dict[str, SemanticStageModel]:
    """Read the tiers a repository declares, rejecting a name nothing will ever match."""

    if not value:
        return {}
    if not isinstance(value, dict):
        raise ValueError("semantic.stage_models must be a mapping")
    tiers: dict[str, SemanticStageModel] = {}
    for tier, entry in value.items():
        name = str(tier).strip().lower()
        if name not in STAGE_TIERS:
            raise ValueError(f"semantic.stage_models keys must be one of {', '.join(STAGE_TIERS)}")
        if not isinstance(entry, dict):
            raise ValueError(f"semantic.stage_models.{name} must be a mapping")
        tiers[name] = _tier(name, entry)
    return tiers


def _tier(name: str, entry: dict[str, Any]) -> SemanticStageModel:
    provider = str(entry.get("provider", "")).strip().lower()
    if provider and provider not in STAGE_PROVIDERS:
        raise ValueError(
            f"semantic.stage_models.{name}.provider must be one of {', '.join(STAGE_PROVIDERS)}"
        )
    return SemanticStageModel(
        provider=provider,
        model=str(entry.get("model", "")).strip(),
        reasoning_effort=str(entry.get("reasoning_effort", "")).strip(),
    )


def stage_tier(request: dict[str, Any]) -> str:
    """Name the kind of work a request is, so a model can be chosen for it."""

    kind = str(request.get("analysis_kind") or "")
    if kind.startswith("taxonomy"):
        return "taxonomy"
    if kind.startswith("synthesis"):
        return "repository" if str(request.get("scope_type")) == "repository" else "group"
    return "module"

"""Executor-neutral token usage parsed from local coding-agent CLI output."""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True, slots=True)
class ProviderUsage:
    """Token usage with one meaning for every executor.

    ``input_tokens`` counts every billed prompt token, cached categories included, so Codex and
    Claude totals are comparable. ``cache_read_input_tokens`` and ``cache_creation_input_tokens``
    are the cached portions of that total, never additions to it. ``reported`` records whether the
    executor actually returned a usage object, so a genuine zero is never confused with silence.
    """

    input_tokens: int = 0
    output_tokens: int = 0
    cache_read_input_tokens: int = 0
    cache_creation_input_tokens: int = 0
    reported: bool = False


def claude_usage(envelope: Any) -> ProviderUsage:
    """Read usage from a ``claude --print --output-format json`` result envelope.

    The envelope's ``usage`` reports the uncached remainder as ``input_tokens`` beside
    ``cache_creation_input_tokens`` and ``cache_read_input_tokens``; the prompt total is their
    sum (see tests/fixtures/claude-print-envelope.json). Without ``usage`` the per-model
    ``modelUsage`` map is summed instead; without either the usage is zero.
    """
    if not isinstance(envelope, dict):
        return ProviderUsage()
    usage = envelope.get("usage")
    if not isinstance(usage, dict) or not usage:
        return _summed_model_usage(envelope.get("modelUsage"))
    cache_read = _count(usage, "cache_read_input_tokens")
    cache_creation = _count(usage, "cache_creation_input_tokens")
    return ProviderUsage(
        input_tokens=_count(usage, "input_tokens") + cache_creation + cache_read,
        output_tokens=_count(usage, "output_tokens"),
        cache_read_input_tokens=cache_read,
        cache_creation_input_tokens=cache_creation,
        reported=True,
    )


def _summed_model_usage(model_usage: Any) -> ProviderUsage:
    if not isinstance(model_usage, dict):
        return ProviderUsage()
    entries = [entry for entry in model_usage.values() if isinstance(entry, dict)]
    cache_read = sum(_count(entry, "cacheReadInputTokens") for entry in entries)
    cache_creation = sum(_count(entry, "cacheCreationInputTokens") for entry in entries)
    uncached = sum(_count(entry, "inputTokens") for entry in entries)
    return ProviderUsage(
        input_tokens=uncached + cache_creation + cache_read,
        output_tokens=sum(_count(entry, "outputTokens") for entry in entries),
        cache_read_input_tokens=cache_read,
        cache_creation_input_tokens=cache_creation,
        reported=bool(entries),
    )


def codex_usage(events: str) -> ProviderUsage:
    """Read usage from the last ``usage`` event of a ``codex exec --json`` stream.

    Codex reports ``input_tokens`` as the whole prompt and ``cached_input_tokens`` plus
    ``cache_write_input_tokens`` as portions of it (see tests/fixtures/codex-exec-events.jsonl),
    so the total is taken as reported rather than summed.
    """
    usage: dict[str, Any] = {}
    for line in events.splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event, dict) and isinstance(event.get("usage"), dict):
            usage = event["usage"]
    return ProviderUsage(
        input_tokens=_count(usage, "input_tokens", "total_input_tokens"),
        output_tokens=_count(usage, "output_tokens", "total_output_tokens"),
        cache_read_input_tokens=_count(usage, "cached_input_tokens"),
        cache_creation_input_tokens=_count(usage, "cache_write_input_tokens"),
        reported=bool(usage),
    )


def _count(mapping: dict[str, Any], *keys: str) -> int:
    """Return the first non-empty key as a non-negative count, or zero."""
    for key in keys:
        value = mapping.get(key)
        if not value:
            continue
        try:
            return max(0, int(value))
        except (TypeError, ValueError):
            return 0
    return 0

"""Deterministic validation, repair, and stable identity for semantic taxonomies."""

from __future__ import annotations

import re
import sqlite3
from collections import Counter, defaultdict
from typing import Any

from anaxigraph.semantic_taxonomy_identity import stable_taxonomy_nodes

_INTERNAL_GROUP_REFERENCE = re.compile(r"\b(?:cluster|group)-\d+\b", re.IGNORECASE)
_TAXONOMY_STOP_WORDS = {
    "and",
    "anaxigraph",
    "code",
    "file",
    "files",
    "for",
    "from",
    "into",
    "module",
    "modules",
    "repository",
    "src",
    "that",
    "the",
    "these",
    "this",
    "with",
    "work",
}


def normalize_taxonomy(
    connection: sqlite3.Connection,
    *,
    repository_id: int,
    snapshot_id: int,
    value: dict[str, Any],
    eligible_paths: list[str],
    settings: dict[str, Any],
    locked_memberships: dict[str, str],
) -> dict[str, Any]:
    known_paths = set(eligible_paths)
    artifacts = _artifact_ids(connection, repository_id, known_paths)
    nodes, candidates, issues = _flatten(value, known_paths)
    _plain_language_issues(nodes, candidates, issues)
    assignments = _primary_assignments(candidates, issues)
    _apply_locks(nodes, assignments, locked_memberships, known_paths, issues)
    _assign_missing(nodes, assignments, known_paths, issues)
    _prune_empty(nodes, assignments)
    _bound_areas(nodes, assignments, int(settings.get("max_areas") or 6), issues)
    _bound_subsystems(nodes, assignments, int(settings.get("max_subsystems") or 30), issues)
    _prune_empty(nodes, assignments)
    stable_nodes, events = stable_taxonomy_nodes(
        connection,
        repository_id=repository_id,
        snapshot_id=snapshot_id,
        nodes=nodes,
        assignments=assignments,
        stability_bias=float(settings.get("stability_bias") or 0.8),
    )
    memberships = _memberships(assignments, stable_nodes, artifacts, locked_memberships)
    _group_shape_issues(stable_nodes, memberships, issues)
    repairs = [issue for issue in issues if issue["kind"].startswith("repaired_")]
    return {
        "summary": str(value.get("summary") or "")[:4_000],
        "confidence": max(0.0, min(1.0, float(value.get("confidence") or 0))),
        "facets": _facets(value.get("facets"), known_paths),
        "nodes": stable_nodes,
        "memberships": memberships,
        "events": events,
        "validation": {
            "status": "adjusted" if repairs else "valid",
            "eligible_modules": len(known_paths),
            "assigned_modules": len(memberships),
            "areas": sum(node["level"] == "area" for node in stable_nodes),
            "subsystems": sum(node["level"] == "subsystem" for node in stable_nodes),
            "repairs": len(repairs),
            "issues": issues,
        },
    }


def _flatten(
    value: dict[str, Any], known_paths: set[str]
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    nodes: dict[str, dict[str, Any]] = {}
    memberships: list[dict[str, Any]] = []
    issues: list[dict[str, Any]] = []
    used: set[str] = set()
    for area_index, area in enumerate(value.get("areas") or []):
        area_key = _unique_key(_slug(area.get("key") or area.get("name") or "area"), used)
        nodes[area_key] = _node(area, area_key, "area", None, area_index)
        for subsystem_index, subsystem in enumerate(area.get("subsystems") or []):
            proposed = _slug(subsystem.get("key") or subsystem.get("name") or "subsystem")
            key = _unique_key(proposed, used)
            nodes[key] = _node(subsystem, key, "subsystem", area_key, subsystem_index)
            for member in subsystem.get("members") or []:
                path = str(member.get("path") or "")
                if path not in known_paths:
                    issues.append(_issue("ignored_unknown_module", path, "warning"))
                    continue
                memberships.append({**member, "path": path, "node_key": key})
    return nodes, memberships, issues


def _node(
    value: dict[str, Any], key: str, level: str, parent: str | None, order: int
) -> dict[str, Any]:
    return {
        "temp_key": key,
        "name": str(value.get("name") or key.replace("-", " ").title())[:250],
        "level": level,
        "parent_temp_key": parent,
        "description": str(value.get("description") or "")[:2_000],
        "responsibility": str(value.get("responsibility") or "")[:2_000],
        "confidence": max(0.0, min(1.0, float(value.get("confidence") or 0))),
        "rationale": str(value.get("rationale") or "")[:4_000],
        "evidence": _strings(value.get("evidence")),
        "counter_evidence": _strings(value.get("counter_evidence")),
        "display_order": order,
        "locked": False,
    }


def _plain_language_issues(
    nodes: dict[str, dict[str, Any]],
    memberships: list[dict[str, Any]],
    issues: list[dict[str, Any]],
) -> None:
    for key, node in nodes.items():
        for field in ("name", "description", "responsibility", "rationale"):
            if _INTERNAL_GROUP_REFERENCE.search(str(node.get(field) or "")):
                issues.append(
                    _issue("unexplained_internal_group_reference", f"{key}.{field}", "warning")
                )
    for membership in memberships:
        if _INTERNAL_GROUP_REFERENCE.search(str(membership.get("rationale") or "")):
            issues.append(
                _issue(
                    "unexplained_internal_group_reference",
                    f"{membership['path']}.rationale",
                    "warning",
                )
            )


def _primary_assignments(
    candidates: list[dict[str, Any]], issues: list[dict[str, Any]]
) -> dict[str, dict[str, Any]]:
    grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for candidate in candidates:
        grouped[candidate["path"]].append(candidate)
    assignments = {}
    for path, values in grouped.items():
        values.sort(key=lambda item: float(item.get("confidence") or 0), reverse=True)
        assignments[path] = values[0]
        if len(values) > 1:
            issues.append(_issue("repaired_duplicate_membership", path, "warning"))
    return assignments


def _apply_locks(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    locks: dict[str, str],
    known_paths: set[str],
    issues: list[dict[str, Any]],
) -> None:
    for path, requested in locks.items():
        if path not in known_paths:
            continue
        target = next(
            (
                key
                for key, node in nodes.items()
                if node["level"] == "subsystem"
                and requested in {key, node["name"], _slug(node["name"])}
            ),
            None,
        )
        if target is None:
            parent = next((key for key, node in nodes.items() if node["level"] == "area"), None)
            if parent is None:
                parent = _unique_key("operator-hints", set(nodes))
                nodes[parent] = _fallback_node(parent, "Operator hints", "area", None)
            target = _unique_key(_slug(requested), set(nodes))
            nodes[target] = _fallback_node(target, requested, "subsystem", parent)
        nodes[target]["locked"] = True
        assignments[path] = {
            "path": path,
            "node_key": target,
            "confidence": 1.0,
            "rationale": "Membership locked by repository map configuration.",
            "evidence": [f"map.locked_memberships: {path}"],
            "alternatives": [],
        }
        issues.append(_issue("applied_locked_membership", path, "info"))


def _assign_missing(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    known_paths: set[str],
    issues: list[dict[str, Any]],
) -> None:
    missing = sorted(known_paths - set(assignments))
    if not missing:
        return
    parent = _unique_key("needs-classification", set(nodes))
    nodes[parent] = _fallback_node(parent, "Needs classification", "area", None)
    subsystem = _unique_key("unclassified-modules", set(nodes))
    nodes[subsystem] = _fallback_node(subsystem, "Unclassified modules", "subsystem", parent)
    for path in missing:
        assignments[path] = {
            "path": path,
            "node_key": subsystem,
            "confidence": 0.0,
            "rationale": (
                "The agent omitted this eligible module; deterministic repair keeps it visible "
                "for the next autonomous map revision."
            ),
            "evidence": [],
            "alternatives": [],
        }
        issues.append(_issue("repaired_missing_membership", path, "warning"))


def _prune_empty(nodes: dict[str, dict[str, Any]], assignments: dict[str, dict[str, Any]]) -> None:
    used_subsystems = {item["node_key"] for item in assignments.values()}
    for key in list(nodes):
        if nodes[key]["level"] == "subsystem" and key not in used_subsystems:
            del nodes[key]
    used_areas = {
        node["parent_temp_key"] for node in nodes.values() if node["level"] == "subsystem"
    }
    for key in list(nodes):
        if nodes[key]["level"] == "area" and key not in used_areas:
            del nodes[key]


def _bound_areas(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    maximum: int,
    issues: list[dict[str, Any]],
) -> None:
    areas = [key for key, node in nodes.items() if node["level"] == "area"]
    if len(areas) <= maximum:
        return
    counts = Counter(item["node_key"] for item in assignments.values())
    area_sizes = {
        area: sum(counts[key] for key, node in nodes.items() if node["parent_temp_key"] == area)
        for area in areas
    }
    ordered = sorted(areas, key=lambda key: (-area_sizes[key], key))
    kept = set(ordered[: max(1, maximum)])
    merges = []
    for area in ordered:
        if area in kept:
            continue
        target = _closest_area(area, kept, nodes, assignments, area_sizes)
        for node in nodes.values():
            if node["level"] == "subsystem" and node["parent_temp_key"] == area:
                node["parent_temp_key"] = target
        merges.append(f"{area}->{target}")
        del nodes[area]
    issues.append(
        _issue("repaired_area_limit", f"{len(areas)} areas; " + ", ".join(merges), "warning")
    )


def _closest_area(
    source: str,
    candidates: set[str],
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    area_sizes: dict[str, int],
) -> str:
    source_terms = _area_terms(source, nodes, assignments)

    def rank(candidate: str) -> tuple[float, int, int, str]:
        candidate_terms = _area_terms(candidate, nodes, assignments)
        shared = len(source_terms & candidate_terms)
        union = len(source_terms | candidate_terms)
        similarity = shared / union if union else 0.0
        return (-similarity, -shared, area_sizes[candidate], candidate)

    return min(candidates, key=rank)


def _area_terms(
    area: str,
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
) -> set[str]:
    subsystems = {
        key
        for key, node in nodes.items()
        if node["level"] == "subsystem" and node["parent_temp_key"] == area
    }
    values = [area]
    for key in {area, *subsystems}:
        node = nodes[key]
        values.extend(
            str(node.get(field) or "")
            for field in ("name", "description", "responsibility", "rationale")
        )
    values.extend(
        path for path, assignment in assignments.items() if assignment["node_key"] in subsystems
    )
    return {
        token
        for token in re.findall(r"[a-z0-9]+", " ".join(values).lower())
        if len(token) > 2 and token not in _TAXONOMY_STOP_WORDS
    }


def _bound_subsystems(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    maximum: int,
    issues: list[dict[str, Any]],
) -> None:
    subsystems = [key for key, node in nodes.items() if node["level"] == "subsystem"]
    if len(subsystems) <= maximum:
        return
    counts = Counter(item["node_key"] for item in assignments.values())
    locked = {key for key in subsystems if nodes[key]["locked"]}
    if len(locked) >= maximum:
        _bound_locked_subsystems(nodes, assignments, subsystems, locked, issues)
        return
    ordered = sorted(
        subsystems,
        key=lambda key: (not nodes[key]["locked"], -counts[key], key),
    )
    kept = set(locked)
    for key in ordered:
        if len(kept) >= maximum - 1:
            break
        kept.add(key)
    moved = set(subsystems) - kept
    _merge_subsystems(nodes, assignments, moved, nodes[ordered[0]]["parent_temp_key"])
    issues.append(_issue("repaired_subsystem_limit", str(len(subsystems)), "warning"))


def _bound_locked_subsystems(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    subsystems: list[str],
    locked: set[str],
    issues: list[dict[str, Any]],
) -> None:
    unlocked = set(subsystems) - locked
    if unlocked:
        parent = nodes[sorted(locked)[0]]["parent_temp_key"]
        _merge_subsystems(nodes, assignments, unlocked, parent)
        issues.append(
            _issue("repaired_subsystem_limit_with_locked_overflow", str(len(unlocked)), "warning")
        )
    issues.append(_issue("subsystem_limit_overridden_by_locks", str(len(locked)), "warning"))


def _merge_subsystems(
    nodes: dict[str, dict[str, Any]],
    assignments: dict[str, dict[str, Any]],
    moved: set[str],
    parent: str | None,
) -> None:
    overflow = _unique_key("other-modules", set(nodes))
    nodes[overflow] = _fallback_node(overflow, "Other modules", "subsystem", parent)
    for assignment in assignments.values():
        if assignment["node_key"] in moved:
            assignment["node_key"] = overflow
            assignment["confidence"] = min(float(assignment.get("confidence") or 0), 0.4)
    for subsystem in moved:
        del nodes[subsystem]


def _memberships(
    assignments: dict[str, dict[str, Any]],
    nodes: list[dict[str, Any]],
    artifacts: dict[str, int],
    locks: dict[str, str],
) -> list[dict[str, Any]]:
    stable = {node["temp_key"]: node["node_key"] for node in nodes}
    result = []
    for path, assignment in sorted(assignments.items()):
        if path not in artifacts:
            continue
        result.append(
            {
                "artifact_id": artifacts[path],
                "path": path,
                "node_key": stable[assignment["node_key"]],
                "confidence": max(0.0, min(1.0, float(assignment.get("confidence") or 0))),
                "rationale": str(assignment.get("rationale") or "")[:4_000],
                "evidence": _strings(assignment.get("evidence")),
                "alternatives": _strings(assignment.get("alternatives")),
                "locked": path in locks,
            }
        )
    return result


def _group_shape_issues(
    nodes: list[dict[str, Any]],
    memberships: list[dict[str, Any]],
    issues: list[dict[str, Any]],
) -> None:
    counts = Counter(item["node_key"] for item in memberships)
    total = max(1, len(memberships))
    for node in nodes:
        if node["level"] != "subsystem":
            continue
        count = counts[node["node_key"]]
        if count == 1:
            issues.append(_issue("tiny_subsystem", node["node_key"], "info"))
        if count / total > 0.5:
            issues.append(_issue("large_catchall_candidate", node["node_key"], "warning"))


def _facets(value: Any, known_paths: set[str]) -> list[dict[str, Any]]:
    result = []
    for item in value or []:
        result.append(
            {
                "name": str(item.get("name") or "")[:250],
                "description": str(item.get("description") or "")[:2_000],
                "members": [path for path in _strings(item.get("members")) if path in known_paths],
                "evidence": _strings(item.get("evidence")),
            }
        )
    return result[:100]


def _artifact_ids(
    connection: sqlite3.Connection, repository_id: int, paths: set[str]
) -> dict[str, int]:
    if not paths:
        return {}
    placeholders = ",".join("?" for _ in paths)
    rows = connection.execute(
        f"SELECT id, canonical_path FROM artifacts WHERE repository_id = ? AND canonical_path IN ({placeholders})",
        (repository_id, *sorted(paths)),
    ).fetchall()
    return {str(row["canonical_path"]): int(row["id"]) for row in rows}


def _fallback_node(key: str, name: str, level: str, parent: str | None) -> dict[str, Any]:
    return {
        "temp_key": key,
        "name": name[:250],
        "level": level,
        "parent_temp_key": parent,
        "description": "Deterministically retained so every module stays visible.",
        "responsibility": "Holds low-confidence or overflow semantic-map membership.",
        "confidence": 0.0,
        "rationale": "Created by deterministic taxonomy validation.",
        "evidence": [],
        "counter_evidence": [],
        "display_order": 10_000,
        "locked": False,
    }


def _issue(kind: str, scope: str, severity: str) -> dict[str, Any]:
    return {"kind": kind, "scope": scope, "severity": severity}


def _slug(value: Any) -> str:
    result = re.sub(r"[^a-z0-9]+", "-", str(value).strip().lower()).strip("-")
    return result[:120] or "unnamed"


def _unique_key(value: str, used: set[str]) -> str:
    if value not in used:
        used.add(value)
        return value
    index = 2
    while f"{value}-{index}" in used:
        index += 1
    result = f"{value}-{index}"
    used.add(result)
    return result


def _strings(value: Any) -> list[str]:
    return [str(item)[:2_000] for item in (value or [])[:100]] if isinstance(value, list) else []

"""Build exact evidence packets for the fixed fresh-eyes review stages."""

from __future__ import annotations

import json
from typing import Any

from anaxigraph.semantic import SEMANTIC_SCHEMA_VERSION
from anaxigraph.semantic_evidence_selection import bounded_evidence
from anaxigraph.semantic_fresh_eyes_contract import (
    FRESH_EYES_PROTOCOL_VERSION,
    semantic_input_hash,
)
from anaxigraph.semantic_fresh_eyes_diversity import proposal_diversity
from anaxigraph.semantic_graph import SupersededSemanticJob
from anaxigraph.semantic_index_port import SemanticIndex
from anaxigraph.understandability import AGENT_REVIEW_POLICY, UNDERSTANDABILITY_POLICY

_DECLARED_CONTEXT_NOTE = (
    " Any entries in declared_context are principal-declared facts about this system, each beside "
    "the inferred claim it targets; disposition 'refute' declares that inferred claim a known "
    "non-issue. Name the declared key when you rely on one, and dispute one only with cited "
    "counter-evidence."
)
_CONTRACTS = {
    "fresh_proposal": (
        "Design a clean-sheet software architecture that delivers the supplied behavior and "
        "constraints. You have deliberately not been shown the existing implementation. Define "
        "the smallest useful responsibilities, boundaries, information flows, extension strategy, "
        "operating model, and justified patterns. Explain trade-offs and avoid infrastructure the "
        "stated scale does not need. Cite capability or constraint evidence, not repository paths."
    ),
    "fresh_adjudication": (
        "Blindly adjudicate the independent clean-sheet proposals using only the same Capability "
        "Brief. Preserve meaningful disagreement, identify shared assumptions and likely common "
        "blind spots, and synthesize the strongest compatible reference design. Agreement is not "
        "proof. Do not infer or discuss the current repository implementation."
    ),
    "fresh_comparison": (
        "Compare the blind reference design with the supplied current system. Search as carefully "
        "for existing strengths and justified differences as for weaknesses. Map responsibilities, "
        "classify every material difference using the allowed result labels, and do not treat an "
        "idea's absence from the clean-sheet design as evidence that current code should be deleted."
        " Apply review_goal when supplied: trace the affected user flows, responsibility owners, "
        "and caller contracts, and distinguish actual inconsistencies from justified differences."
        + _DECLARED_CONTEXT_NOTE
    ),
    "fresh_review": (
        "Filter the comparison into a small ranked refactor strategy. Keep only changes that "
        "materially advance the mission after accounting for user value, coherence, expected code "
        "reduction, operational simplicity, compatibility, migration risk, reversibility, and "
        "verification cost. Reject attractive overengineering. This is advice, not permission to "
        "edit code, and retaining the current design is valid when evidence supports it."
        " Apply review_goal when supplied; tie each proposed change to an evidenced user outcome "
        "and say what existing machinery it replaces or why extra concepts are justified."
        + _DECLARED_CONTEXT_NOTE
    ),
}
_INPUT_CONTRACTS = {
    "fresh_proposal": "fresh-eyes-proposal-v1",
    "fresh_adjudication": "fresh-eyes-adjudication-v1",
    "fresh_comparison": "fresh-eyes-comparison-v1",
    "fresh_review": "fresh-eyes-review-v1",
}


def fresh_eyes_request(
    database: SemanticIndex,
    job: dict[str, Any],
) -> dict[str, Any]:
    kind = str(job["job_kind"])
    if kind not in _CONTRACTS:
        raise ValueError(f"unsupported fresh-eyes job kind: {kind}")
    metadata = job["metadata"]
    _validate_manifest(job, metadata)
    request = {
        "contract": _CONTRACTS[kind] + " " + AGENT_REVIEW_POLICY,
        "schema_version": SEMANTIC_SCHEMA_VERSION,
        "protocol_version": FRESH_EYES_PROTOCOL_VERSION,
        "analysis_kind": kind,
        "input_manifest": metadata["input_manifest"],
        "information_boundary": metadata["information_boundary"],
        "understandability_policy": UNDERSTANDABILITY_POLICY,
    }
    request.update(_stage_evidence(database, kind, metadata))
    if kind in {"fresh_comparison", "fresh_review"} and metadata["input_manifest"].get(
        "review_goal"
    ):
        request["review_goal"] = metadata["input_manifest"]["review_goal"]["text"]
    return bounded_evidence(request)


def _stage_evidence(
    database: SemanticIndex,
    kind: str,
    metadata: dict[str, Any],
) -> dict[str, Any]:
    if kind == "fresh_proposal":
        return _proposal_evidence(metadata)
    if kind == "fresh_adjudication":
        return _adjudication_evidence(database, metadata)
    if kind == "fresh_comparison":
        adjudication = _document(database, metadata["adjudication_document_id"])
        return {
            "capability_brief": metadata["capability_brief"],
            "reference_design": adjudication["value"]["reference_design"],
            "current_system": metadata["current_system"],
        }
    return _review_evidence(database, metadata)


def _review_evidence(database: SemanticIndex, metadata: dict[str, Any]) -> dict[str, Any]:
    comparison = _document(database, metadata["comparison_document_id"])
    evidence = {
        "capability_brief": metadata["capability_brief"],
        "comparison": comparison["value"],
        "engineering_economics": {
            "prefer": [
                "small coherent changes",
                "deleting or consolidating code when behavior is preserved",
                "reversible steps with explicit verification",
                "retaining good existing decisions",
                "making representative maintenance tasks easier using the repository itself",
            ],
            "reject": [
                "speculative infrastructure",
                "rewrites without capability benefit",
                "new abstractions whose migration cost exceeds likely value",
                "file splitting or documentation deletion without a concrete reader benefit",
            ],
        },
    }
    if metadata.get("declared_context"):
        evidence["declared_context"] = metadata["declared_context"]
    return evidence


def _proposal_evidence(metadata: dict[str, Any]) -> dict[str, Any]:
    return {
        "proposal_slot": metadata["slot"],
        "capability_brief": metadata["capability_brief"],
        "external_constraints": metadata["external_constraints"],
        "isolation_request": {
            "mode": "fresh_context",
            "instruction": (
                "Use a fresh subagent or session when the host supports it; otherwise report "
                "isolation as unverified."
            ),
        },
    }


def _adjudication_evidence(database: SemanticIndex, metadata: dict[str, Any]) -> dict[str, Any]:
    proposals = _documents(database, metadata["proposal_document_ids"])
    return {
        "capability_brief": metadata["capability_brief"],
        "proposals": [
            {
                "proposal": item["scope_key"],
                "value": item["value"],
                "reviewer": _reviewer(item),
            }
            for item in proposals
        ],
        "diversity": proposal_diversity(proposals),
    }


def _documents(database: SemanticIndex, document_ids: list[int]) -> list[dict[str, Any]]:
    with database.connect() as connection:
        return [_read_document(connection, int(document_id)) for document_id in document_ids]


def _document(database: SemanticIndex, document_id: int) -> dict[str, Any]:
    with database.connect() as connection:
        return _read_document(connection, int(document_id))


def _read_document(connection: Any, document_id: int) -> dict[str, Any]:
    row = connection.execute(
        "SELECT * FROM semantic_documents WHERE id = ?", (document_id,)
    ).fetchone()
    if row is None:
        raise SupersededSemanticJob(f"Fresh-eyes document {document_id} no longer exists")
    document = dict(row)
    document["value"] = json.loads(document.get("value_json") or "{}")
    return document


def _reviewer(document: dict[str, Any]) -> dict[str, Any]:
    return {
        "provider": document.get("provider"),
        "model": document.get("model"),
        "executor_id": document.get("executor_id"),
        "executor_model": document.get("executor_model"),
        "executor_effort": document.get("executor_effort"),
    }


def _validate_manifest(job: dict[str, Any], metadata: dict[str, Any]) -> None:
    manifest = metadata.get("input_manifest")
    if not isinstance(manifest, dict):
        raise SupersededSemanticJob("Fresh-eyes work no longer has its exact input manifest")
    expected = semantic_input_hash(
        _INPUT_CONTRACTS[str(job["job_kind"])],
        str(job["prompt_version"]),
        manifest,
    )
    if expected != str(job["input_hash"]):
        raise SupersededSemanticJob("Fresh-eyes input manifest no longer matches its planned job")

