    schema_version, confidence, created_at
) VALUES (?, ?, 'fresh_eyes', 'grounding', ?, 'fresh_grounding', ?, ?, ?, 'deterministic',
    'deterministic', '', 'fresh-eyes-grounding-v1', 'fresh-eyes-grounding-v1', 1.0, ?)
"""
_STAGE_SQL = """
SELECT context_document_id FROM semantic_scope_states
WHERE snapshot_id = ? AND scope_type = 'fresh_eyes' AND scope_key = ?
"""
_CHANGED_SQL = """
SELECT DISTINCT c.artifact_id FROM snapshot_file_changes c
JOIN snapshots s ON s.id = c.snapshot_id
WHERE s.repository_id = ? AND c.snapshot_id > ? AND c.snapshot_id <= ?
  AND c.artifact_id IN ({placeholders})
"""


def write_review_grounding(
    connection: Any, *, repository_id: int, snapshot_id: int, review_id: int
) -> int | None:
    """Write one grounding report per review document; later planning passes are no-ops."""

    digest = _grounding_hash(review_id)
    if (stored := _stored(connection, repository_id, digest)) is not None:
        return int(stored["id"])
    review = _value(connection, review_id)
    if review is None:
        return None
    stage = connection.execute(_STAGE_SQL, (snapshot_id, "comparison")).fetchone()
    value = ground_review(
        connection,
        repository_id=repository_id,
        snapshot_id=snapshot_id,
        review_value=review,
        comparison_value=_value(connection, stage["context_document_id"] if stage else 0),
        declared_context=read_charter_corrections(connection, repository_id),
    )
    encoded = json.dumps(value, sort_keys=True)
    now = datetime.now(UTC).isoformat()
    cursor = connection.execute(
        _INSERT_SQL, (repository_id, snapshot_id, int(review_id), digest, digest, encoded, now)
    )
    return int(cursor.lastrowid)


def read_review_grounding(
    connection: Any, *, repository_id: int, snapshot_id: int, review_id: Any
) -> dict[str, Any] | None:
    """Read the stored report and overlay staleness for the reported snapshot; never writes."""

    if not review_id:
        return None
    value = _stored_value(connection, repository_id, int(review_id))
    if value is None:
        return None
    return _with_staleness(connection, repository_id, value, int(snapshot_id))


def with_grounding(connection: Any, payload: dict[str, Any], *, review_id: Any) -> dict[str, Any]:
    """Attach the deterministic grounding report to one review status payload."""

    grounding = read_review_grounding(
        connection,
        repository_id=int(payload["repository_id"]),
        snapshot_id=int(payload["snapshot_id"]),
        review_id=review_id,
    )
    payload["grounding_summary"] = grounding["summary"] if grounding else None
    if grounding is None:
        return payload
    by_rank = {int(item["rank"]): item for item in grounding["recommendations"]}
    payload["recommendations"] = [
        {**item, "grounding": _for_rank(by_rank, item)} for item in payload["recommendations"]
    ]
    payload["caveats"] = [*payload.get("caveats", []), GROUNDING_CAVEAT]
    return payload


def ground_review(
    connection: Any,
    *,
    repository_id: int,
    snapshot_id: int,
    review_value: dict[str, Any],
    comparison_value: dict[str, Any] | None = None,
    declared_context: Any = (),
) -> dict[str, Any]:
    """Label every recommendation from the identifiers it cites, and say how that was decided."""

    index = snapshot_index(connection, snapshot_id, declared_context)
    candidates = (comparison_value or {}).get("candidate_changes") or []
    classifications = {
        _normalized(item.get("title")): str(item.get("classification") or "") for item in candidates
    }
    grounded = [
        _ground_recommendation(connection, repository_id, index, item, classifications)
        for item in (review_value.get("recommendations") or [])
    ]
    return {
        "contract_version": FRESH_EYES_GROUNDING_VERSION,
        "method": GROUNDING_METHOD,
        "snapshot_id": int(snapshot_id),
        "recommendations": grounded,
        "summary": _summary(grounded, int(snapshot_id), int(snapshot_id)),
        "caveats": list(GROUNDING_CAVEATS),
    }


def _ground_recommendation(
    connection: Any,
    repository_id: int,
    index: SnapshotIndex,
    recommendation: dict[str, Any],
    classifications: dict[str, str],
) -> dict[str, Any]:
    checks = [
        resolve_identifier(connection, repository_id, index, kind, value, field)
        for kind, value, field in cited_identifiers(recommendation)
    ]
    status, reason = _status(recommendation, checks, classifications)
    return {
        "rank": int(recommendation.get("rank") or 0),
        "title": str(recommendation.get("title") or ""),
        "status": status,
        "reason": reason,
        "evidence_state": _evidence_state(checks, recommendation),
        "checks": checks,
    }


def _evidence_state(
    checks: list[dict[str, Any]], recommendation: dict[str, Any] | None = None
) -> dict[str, str]:
    """Say which of the three evidence questions this pass actually answered."""

    if not checks:
        resolution = "none_cited"
    elif any(check["result"] != "exists" for check in checks):
        resolution = "unresolved"
    else:
        resolution = "resolved"
    return {
        "reference_resolution": resolution,
        "claim_support": _UNCHECKED,
        "behavior_verification": attributed_verification(recommendation or {}),
    }


def _status(
    recommendation: dict[str, Any], checks: list[dict[str, Any]], classifications: dict[str, str]
) -> tuple[str, str]:
    resolved = [check for check in checks if check["result"] == "exists"]
    missing = [check for check in checks if check["result"] == "missing"]
    if satisfied := _already_satisfied(recommendation, classifications):
        return "already_satisfied", satisfied
    if present := _name_already_present(recommendation, resolved):
        return "name_already_present", present
    if not checks:
        return "needs_test", "The recommendation cites no checkable identifier."
    if missing:
        names = ", ".join(f"{check['kind']} {check['value']}" for check in missing)
        return "needs_test", (
            f"{len(resolved)} of {len(checks)} cited identifiers resolve in the reviewed "
            f"snapshot; {names} could not be found."
        )
    return "references_resolved", (
        f"All {len(checks)} cited identifiers resolve in the reviewed snapshot. That locates the "
        "recommendation in real code; it does not support its claim."
    )


def _already_satisfied(recommendation: dict[str, Any], classifications: dict[str, str]) -> str:
    """Report only a judgment another stage actually made, never one inferred from a name."""

    if classifications.get(_normalized(recommendation.get("title"))) == "already_satisfies":
        return "The comparison stage classified the matching candidate already_satisfies."
    if str(recommendation.get("action") or "") == "retain":
        return "The recommendation asks to retain what the repository already does."
    return ""


def _name_already_present(recommendation: dict[str, Any], resolved: list[dict[str, Any]]) -> str:
    """A proposed name that already resolves is worth reading, but it is not proof of behavior."""

    introduced = [
        check
        for check in resolved
        if check["field"] == "smallest_change" and check["kind"] in {"route", "symbol"}
    ]
    smallest = str(recommendation.get("smallest_change") or "").lower()
    if introduced and _INTRODUCES.search(smallest):
        return (
            f"The proposed {introduced[0]['kind']} {introduced[0]['value']} already exists by "
            "name. Read what it does before treating the recommendation as already satisfied."
        )
    return ""
    return ""


def _normalized(value: Any) -> str:
    return " ".join(str(value or "").lower().split())


def _summary(grounded: list[dict[str, Any]], reviewed: int, current: int) -> dict[str, Any]:
    counts = dict.fromkeys(_STATUSES, 0)
    for item in grounded:
        counts[str(item["status"])] = counts.get(str(item["status"]), 0) + 1
    return {
        "contract_version": FRESH_EYES_GROUNDING_VERSION,
        "method": GROUNDING_METHOD,
        "reviewed_snapshot_id": reviewed,
        "current_snapshot_id": current,
        "recommendations": len(grounded),
        "checks": sum(len(item["checks"]) for item in grounded),
        "counts": counts,
    }


def _with_staleness(
    connection: Any, repository_id: int, value: dict[str, Any], snapshot_id: int
) -> dict[str, Any]:
    """Mark a recommendation stale when code it cited changed after the review was produced."""

    reviewed = int(value.get("snapshot_id") or 0)
    grounded = list(value.get("recommendations") or [])
    cited = {
        int(check["artifact_id"])
        for item in grounded
        for check in item.get("checks") or []
        if check.get("artifact_id") is not None
    }
    if cited and snapshot_id > reviewed:
        ordered = sorted(cited)
        rows = connection.execute(
            _CHANGED_SQL.format(placeholders=",".join("?" * len(ordered))),
            (repository_id, reviewed, snapshot_id, *ordered),
        ).fetchall()
        changed = frozenset(int(row["artifact_id"]) for row in rows)
        grounded = [_stale(item, changed) for item in grounded] if changed else grounded
    return {
        **value,
        "recommendations": grounded,
        "summary": _summary(grounded, reviewed, snapshot_id),
    }


def _stale(item: dict[str, Any], changed: frozenset[int]) -> dict[str, Any]:
    checks = item.get("checks") or []
    hits = [check for check in checks if check.get("artifact_id") in changed]
    if not hits:
        return item
    named = ", ".join(str(check["value"]) for check in hits)
    return {
        **item,
        "status": "stale",
        "reason": f"Cited code changed after the review was produced: {named}.",
        "evidence_state": {
            "reference_resolution": "changed",
            "claim_support": _UNCHECKED,
            "behavior_verification": _UNCHECKED,
        },
        "checks": [
            {**check, "result": "changed"} if check.get("artifact_id") in changed else check
            for check in checks
        ],
    }


def _for_rank(by_rank: dict[int, dict[str, Any]], recommendation: dict[str, Any]) -> dict[str, Any]:
    grounded = by_rank.get(int(recommendation.get("rank") or 0))
    if grounded is None:
        reason = "This recommendation was not part of the grounded review document."
        return {
            "status": "needs_test",
            "reason": reason,
            "evidence_state": {
                "reference_resolution": "none_cited",
                "claim_support": _UNCHECKED,
                "behavior_verification": _UNCHECKED,
            },
            "checks": [],
        }
    return {key: value for key, value in grounded.items() if key not in {"rank", "title"}}


def _stored_value(connection: Any, repository_id: int, review_id: int) -> dict[str, Any] | None:
    """Read this contract's report, falling back to one a previous contract wrote.

    A version bump changes the stored identity, so an older report would otherwise disappear.
    Earlier reports stay readable and keep the contract version they were written under; their
    status names are projected onto the current vocabulary without inventing evidence.
    """

    for contract in (FRESH_EYES_GROUNDING_VERSION, *LEGACY_GROUNDING_VERSIONS):
        stored = _stored(connection, repository_id, _grounding_hash(review_id, contract))
        if stored is None:
            continue
        value = json.loads(stored["value_json"] or "{}")
        return value if contract == FRESH_EYES_GROUNDING_VERSION else _projected(value)
    return None


def _projected(value: dict[str, Any]) -> dict[str, Any]:
    """Carry an earlier report forward: rename what it claimed, add nothing it did not check."""

    return {
        **value,
        "recommendations": [_projected_item(item) for item in value.get("recommendations") or []],
    }


def _projected_item(item: dict[str, Any]) -> dict[str, Any]:
    checks = item.get("checks") or []
    status = str(item.get("status") or "")
    reason = str(item.get("reason") or "")
    if status == "confirmed":
        status = "references_resolved"
    elif status == "already_satisfied" and "already exists" in reason:
        status = "name_already_present"
    return {**item, "status": status, "evidence_state": _evidence_state(checks)}


def _grounding_hash(review_id: int, contract: str = FRESH_EYES_GROUNDING_VERSION) -> str:
    return semantic_digest({"contract": contract, "review_document_id": int(review_id)})


def _value(connection: Any, document_id: Any) -> dict[str, Any] | None:
    """Read one stored document value without importing the fresh-eyes generation reader."""

    if not document_id:
        return None
    row = connection.execute(
        "SELECT value_json FROM semantic_documents WHERE id = ?", (document_id,)
    ).fetchone()
    return json.loads(row["value_json"] or "{}") if row else None


def _stored(connection: Any, repository_id: int, input_hash: str) -> dict[str, Any] | None:
    keys = (GROUNDING_SCOPE_TYPE, GROUNDING_SCOPE_KEY, GROUNDING_DOCUMENT_KIND)
    row = connection.execute(_STORED_SQL, (repository_id, *keys, input_hash)).fetchone()
    return dict(row) if row else None

import {
  architectureFor,
  byId,
  escapeAttr,
  escapeHtml,
  format,
  humanize,
  state,
} from "/assets/dashboard-core.js";
import {
  conciseMappingMarkup,
  consolidationMarkup,
  deadCodeList,
  detailList,
  formatDate,
  patternOpportunityExplanation,
  patternOpportunityLabel,
  patternOpportunityList,
  understandabilityMarkup,
} from "/assets/dashboard-format.js";

export function renderModuleFilters() {
  const options = (key) => [...new Set(state.modules.map((item) => {
    if (key === "architecture_area") return architectureFor(item)?.area;
    if (key === "architecture_subsystem") return architectureFor(item)?.subsystem;
    return item[key];
  }).filter(Boolean))].sort((left, right) => String(left).localeCompare(String(right)));
  const populate = (id, values, label, display = humanize) => {
    const select = byId(id);
    const selected = select.value;
    select.innerHTML = `<option value="">All ${label}</option>${values.map((value) => (
      `<option value="${escapeAttr(value)}">${escapeHtml(display(value))}</option>`
    )).join("")}`;
    if (values.includes(selected)) select.value = selected;
  };
  populate("module-area-filter", options("architecture_area"), "areas", (value) => architectureLabel("area", value));
  populate("module-subsystem-filter", options("architecture_subsystem"), "subsystems", (value) => architectureLabel("subsystem", value));
  populate("module-language-filter", options("language"), "languages");
}

function architectureLabel(kind, value) {
  const label = state.modules
    .map((item) => architectureFor(item))
    .find((placement) => placement?.[kind] === value)?.[`${kind}_label`];
  return label || humanize(value);
}

function moduleValue(item, key) {
  if (key === "coupling") return Number(item.fan_in || 0) + Number(item.fan_out || 0);
  if (key === "attention_score") {
    const score = item.evaluation?.attention_score;
    return score == null ? null : Number(score);
  }
  if (key === "architecture_area") {
    const placement = architectureFor(item) || {};
    return placement.area_label || placement.area;
  }
  return item[key];
}

function filteredModules() {
  const query = byId("module-search").value.trim().toLowerCase();
  const sharedSearch = query && state.moduleSearchQuery.toLowerCase() === query
    ? state.moduleSearchResults || []
    : null;
  const area = byId("module-area-filter").value;
  const subsystem = byId("module-subsystem-filter").value;
  const language = byId("module-language-filter").value;
  const includeReference = byId("module-include-reference").checked;
  const filtered = (sharedSearch || state.modules).filter((item) => {
    const evaluation = item.evaluation || {};
    const architecture = architectureFor(item) || {};
    return (includeReference || evaluation.monitored_by_default !== false)
      && (!area || architecture.area === area)
      && (!subsystem || architecture.subsystem === subsystem)
      && (!language || item.language === language);
  });
  return filtered.sort(sharedSearch ? searchOrder : moduleOrder);
}

function searchOrder(left, right) {
  return Number(right.score || 0) - Number(left.score || 0)
    || left.path.localeCompare(right.path);
}

function moduleOrder(left, right) {
  const { key, direction } = state.moduleSort;
  const a = moduleValue(left, key);
  const b = moduleValue(right, key);
  if (a == null && b == null) return left.path.localeCompare(right.path);
  if (a == null) return 1;
  if (b == null) return -1;
  const comparison = typeof a === "number" && typeof b === "number"
    ? a - b
    : String(a).localeCompare(String(b));
  return (direction === "asc" ? comparison : -comparison)
    || left.path.localeCompare(right.path);
}

export function renderModules() {
  const items = filteredModules();
  const pageSize = Number(byId("module-page-size").value || 100);
  const pages = Math.max(1, Math.ceil(items.length / pageSize));
  state.modulePage = Math.min(Math.max(1, state.modulePage), pages);
  const start = (state.modulePage - 1) * pageSize;
  const visible = items.slice(start, start + pageSize);
  const reviewable = state.modules.filter(
    (item) => item.evaluation?.monitored_by_default !== false,
  ).length;
  const hidden = state.modules.length - reviewable;
  byId("module-result-count").textContent = byId("module-include-reference").checked
    ? `${format.format(items.length)} of ${format.format(state.modules.length)} files`
    : `${format.format(items.length)} source or test files · ${format.format(hidden)} reference files hidden`;
  byId("module-page-label").textContent = `Page ${state.modulePage} of ${pages}`;
  byId("module-previous").disabled = state.modulePage <= 1;
  byId("module-next").disabled = state.modulePage >= pages;
  document.querySelectorAll("[data-module-sort]").forEach((button) => {
    const active = button.dataset.moduleSort === state.moduleSort.key;
    button.classList.toggle("active", active);
    if (active) button.dataset.direction = state.moduleSort.direction === "asc" ? "↑" : "↓";
    else delete button.dataset.direction;
  });
  byId("module-table-body").innerHTML = visible.map(moduleRow).join("")
    || '<tr><td colspan="12"><p class="muted">No files match these filters.</p></td></tr>';
}

function moduleRow(item) {
  const evaluation = item.evaluation || {};
  const placement = architectureFor(item) || {};
  const semanticCandidates = item.semantic?.pattern_opportunities || [];
  const candidates = semanticCandidates.length ? semanticCandidates : evaluation.pattern_candidates || [];
  const expanded = Number(state.expandedModuleId) === Number(item.artifact_id);
  const branchMeaning = `File-wide branch score ${format.format(item.complexity)}. This combines branches across all functions; it is not a code-quality grade.`;
  const row = `<tr class="module-row" data-module-id="${item.artifact_id}" aria-expanded="${expanded}"><td><span class="module-name">${escapeHtml(item.name)}</span><code class="module-path">${escapeHtml(item.path)}</code></td><td class="architecture-cell">${architectureMarkup(placement)}</td><td class="module-summary">${escapeHtml(item.summary)}</td><td class="pattern-cell">${patternMarkup(candidates, semanticCandidates, evaluation)}</td><td class="numeric">${format.format(item.lines_of_code)}</td><td class="numeric" title="${escapeAttr(branchMeaning)}">${format.format(item.complexity)}</td><td class="numeric" title="${format.format(item.fan_in)} direct links from other files · ${format.format(item.fan_out)} direct links to other files">${format.format(Number(item.fan_in || 0) + Number(item.fan_out || 0))}</td><td class="numeric">${coverageMarkup(item.line_coverage)}</td><td class="numeric">${format.format(item.change_count || 0)}</td><td>${formatDate(item.first_changed_at)}</td><td>${formatDate(item.last_commit_at)}</td><td class="numeric">${attentionMarkup(evaluation)}</td></tr>`;
  return expanded ? row + moduleDetailRow(item) : row;
}

function coverageMarkup(lineCoverage) {
  return lineCoverage == null
    ? '<span class="coverage-value missing">—</span>'
    : `<span class="coverage-value">${(Number(lineCoverage) * 100).toFixed(0)}%</span>`;
}

function architectureMarkup(placement) {
  const area = placement.area_label || humanize(placement.area || "unclassified");
  const subsystem = placement.subsystem_label || humanize(placement.subsystem || "");
  if (placement.subsystem) {
    return `<strong>${escapeHtml(area)}</strong><span>${escapeHtml(subsystem)}</span>`;
  }
  return `<strong>${escapeHtml(area)}</strong><span>${escapeHtml(placement.source || state.mapLayer)}</span>`;
}

function patternMarkup(candidates, semanticCandidates, evaluation) {
  if (!candidates.length) {
    const emptyLabel = evaluation.monitored_by_default === false
      ? "Not evaluated"
      : "No grounded proposal";
    return `<span class="pattern-none">${emptyLabel}</span>`;
  }
  const more = candidates.length > 1 ? ` +${candidates.length - 1}` : "";
  const source = semanticCandidates.length ? " · AI" : "";
  const title = candidates.map(patternOpportunityExplanation).join(" · ");
  return `<span class="pattern-candidate" title="${escapeAttr(title)}">${escapeHtml(patternOpportunityLabel(candidates[0]))}${more}${source}</span>`;
}

function attentionMarkup(evaluation) {
  if (evaluation.attention_score == null) {
    const meaning = evaluation.attention_score_meaning
      || evaluation.monitoring_reason
      || "Reference file";
    return `<span class="attention-pill reference" title="${escapeAttr(meaning)}">Reference</span>`;
  }
  const attention = String(evaluation.attention_label || "low").toLowerCase();
  const reasons = [
    evaluation.attention_score_meaning,
    ...(evaluation.attention_reasons || []),
  ].filter(Boolean).join(" · ");
  const guidance = evaluation.attention_guidance || evaluation.attention_label || "Background";
  return `<span class="attention-pill ${escapeAttr(attention)}" title="${escapeAttr(reasons)}">${escapeHtml(guidance)}</span>`;
}

function moduleDetailRow(item) {
  const evaluation = item.evaluation || {};
  const candidates = item.semantic?.pattern_opportunities?.length
    ? item.semantic.pattern_opportunities
    : evaluation.pattern_candidates || [];
  const detail = state.moduleDetails.get(item.path);
  const history = [
    item.first_change_commit
      ? `First indexed change ${String(item.first_change_commit).slice(0, 8)} · ${formatDate(item.first_changed_at)}`
      : "No indexed first-change commit",
    item.last_change_commit
      ? `Last change ${String(item.last_change_commit).slice(0, 8)} · ${formatDate(item.last_commit_at)}`
      : "No indexed last-change commit",
    item.last_change_subject || "No commit subject indexed",
  ];
  const semanticPanel = semanticPanelMarkup(item, detail);
  const fingerprints = `Exact file fingerprint ${String(item.raw_hash).slice(0, 12)} · code-structure fingerprint ${String(item.structural_hash).slice(0, 12)}. These identify versions; they are not scores.`;
  return `<tr class="module-detail-row"><td colspan="12"><div class="module-detail"><div><h3>Purpose</h3><p>${escapeHtml(item.summary)}</p><p class="muted">How this purpose was written: ${escapeHtml(item.summary_source)}</p><p><code class="module-path">${escapeHtml(fingerprints)}</code></p><div class="module-detail-actions"><button class="secondary-button" data-module-graph="${escapeAttr(item.path)}" type="button">Open in graph</button></div></div><div><h3>Jobs detected in this file</h3>${detailList(item.responsibilities || [], "No specific job was detected")}<h3>Change history</h3>${detailList(history)}</div>${semanticPanel}<div><h3>${evaluation.monitored_by_default === false ? "Reference file" : "Included when choosing what to inspect first"}</h3><p>${escapeHtml(evaluation.monitoring_reason || "AnaxiGraph includes this source file when choosing what to inspect first.")}</p><h3>When to inspect · ${escapeHtml(evaluation.attention_guidance || "Background")}</h3><p>${escapeHtml(evaluation.attention_score_meaning || "This ordering is not a code-quality grade.")}</p>${detailList(evaluation.attention_reasons)}<h3>Pattern ideas from code checks</h3>${patternOpportunityList(candidates, "No pattern idea has direct code evidence yet")}<p>${escapeHtml(evaluation.note || "")}</p></div></div></td></tr>`;
}

function semanticPanelMarkup(item, detail) {
  if (!detail) return "<div><h3>AI map</h3><p>Loading the saved AI description…</p></div>";
  const intrinsic = detail.semantic_dossiers?.intrinsic?.value ?? {};
  const contextual = detail.semantic_dossiers?.context?.value ?? {};
  const value = contextual.summary ? contextual : intrinsic;
  const language = item.semantic?.plain_language ?? detail.semantic_plain_language ?? {};
  const related = [...(value.similar_modules ?? []), ...(value.overlaps ?? [])];
  const summary = preferredText(language.what_this_file_does, value.summary, item.summary);
  const role = preferredText(language.role_in_repository, value.architecture_role);
  const changed = preferredText(language.what_changed_in_description, value.change_summary);
  const placement = preferredText(language.where_related_work_belongs, value.placement_guidance);
  const extensionPoints = preferredList(language.places_for_adding_behavior, value.extension_points);
  const risks = preferredList(language.risks_and_uncertainty, value.risks);
  const mapState = preferredText(
    language.conclusion,
    "The AI map has not described this file yet.",
  );
  const concise = conciseMappingMarkup(value);
  if (concise) return `<div><h3>AI map</h3><p>${escapeHtml(mapState)}</p>${concise}</div>`;
  return `<div><h3>AI map</h3><p>${escapeHtml(mapState)}</p><h3>What this file does</h3><p>${escapeHtml(summary)}</p>${optionalSection("Role in this repository", role)}${optionalSection("What changed in this AI description", changed)}<h3>Files with related or overlapping work</h3>${optionalParagraph(language.related_file_evidence)}${detailList(related, "The AI map did not identify related or overlapping files")}<h3>Places designed for adding behavior</h3>${detailList(extensionPoints, "The AI map did not identify a specific place for adding behavior")}<h3>Patterns that may fit</h3>${patternOpportunityList(value.pattern_opportunities)}${consolidationMarkup(value.consolidation_assessment)}${understandabilityMarkup(value.understandability, detail.semantic_state?.status)}${optionalSection("Where related work belongs", placement)}<h3>Code that may no longer be used</h3>${deadCodeList(value.dead_code_candidates)}<h3>Risks and uncertainty</h3>${detailList(risks, "The AI map did not record a specific risk")}</div>`;
}

function preferredText(...values) {
  return values.find((value) => typeof value === "string" && value.length) ?? "";
}

function preferredList(primary, fallback) {
  return Array.isArray(primary) ? primary : fallback ?? [];
}

function optionalSection(title, value) {
  return value ? `<h3>${escapeHtml(title)}</h3><p>${escapeHtml(value)}</p>` : "";
}

function optionalParagraph(value) {
  return value ? `<p class="muted">${escapeHtml(value)}</p>` : "";
}

import { api, byId, request, state, toast } from "/assets/dashboard-core.js";
import { inspectNode } from "/assets/graph-view.js";
import { renderModules } from "/assets/module-view.js";
import { switchView } from "/assets/navigation.js";

let searchTimer = null;

export function setupModuleEvents() {
  byId("module-search").addEventListener("input", scheduleModuleSearch);
  [
    "module-area-filter", "module-subsystem-filter", "module-language-filter",
    "module-include-reference", "module-page-size",
  ].forEach((id) => byId(id).addEventListener("change", resetAndRender));
  document.querySelectorAll("[data-module-sort]").forEach((button) => {
    button.addEventListener("click", () => {
      const key = button.dataset.moduleSort;
      state.moduleSort = state.moduleSort.key === key
        ? { key, direction: state.moduleSort.direction === "asc" ? "desc" : "asc" }
        : { key, direction: ["path", "architecture_area", "summary"].includes(key) ? "asc" : "desc" };
      resetAndRender();
    });
  });
  byId("module-previous").addEventListener("click", () => {
    state.modulePage -= 1;
    renderModules();
  });
  byId("module-next").addEventListener("click", () => {
    state.modulePage += 1;
    renderModules();
  });
  byId("module-table-body").addEventListener("click", handleModuleClick);
}

function scheduleModuleSearch() {
  window.clearTimeout(searchTimer);
  state.modulePage = 1;
  const query = byId("module-search").value.trim();
  if (query.length < 2) {
    state.moduleSearchResults = null;
    state.moduleSearchQuery = "";
    state.moduleSearchToken += 1;
    renderModules();
    return;
  }
  const searchToken = ++state.moduleSearchToken;
  const repositoryToken = state.repositoryLoadToken;
  state.moduleSearchResults = [];
  state.moduleSearchQuery = query;
  renderModules();
  searchTimer = window.setTimeout(async () => {
    try {
      const result = await request(api("/api/search", { q: query, limit: 250 }));
      if (
        searchToken !== state.moduleSearchToken
        || repositoryToken !== state.repositoryLoadToken
        || byId("module-search").value.trim() !== query
      ) return;
      state.moduleSearchResults = result.results || [];
      renderModules();
    } catch (error) {
      if (searchToken === state.moduleSearchToken) toast(error.message, true);
    }
  }, 180);
}

function resetAndRender() {
  state.modulePage = 1;
  renderModules();
}

async function handleModuleClick(event) {
  const graphButton = event.target.closest("[data-module-graph]");
  if (graphButton) {
    const node = state.graph.nodes.find((item) => item.path === graphButton.dataset.moduleGraph);
    if (node) {
      switchView("graph");
      window.setTimeout(() => inspectNode(node), 0);
    }
    return;
  }
  const row = event.target.closest(".module-row");
  if (!row) return;
  const id = Number(row.dataset.moduleId);
  state.expandedModuleId = Number(state.expandedModuleId) === id ? null : id;
  renderModules();
  if (Number(state.expandedModuleId) !== id) return;
  const item = [...(state.moduleSearchResults || []), ...state.modules]
    .find((candidate) => Number(candidate.artifact_id) === id);
  if (!item || state.moduleDetails.has(item.path)) return;
  const repositoryLoadToken = state.repositoryLoadToken;
  try {
    const detail = await request(api("/api/file", {
      path: item.path,
      snapshot_id: state.overview?.snapshot?.id,
    }));
    if (repositoryLoadToken !== state.repositoryLoadToken) return;
    state.moduleDetails.set(item.path, detail);
    if (Number(state.expandedModuleId) === id) renderModules();
  } catch (error) {
    if (repositoryLoadToken === state.repositoryLoadToken) toast(error.message, true);
  }
}
